/**
 * TASK: Complete LogLevelParser. The LogLevel enum above it is provided --
 * do not edit it.
 *
 * - parseOrDefault(text, fallback) returns the matching LogLevel. The text may
 *   have surrounding spaces and any capitalisation ("  warn " -> WARN). A null
 *   text, an empty text or a name that is not a level returns the fallback
 *   instead of throwing. LogLevel.valueOf throws IllegalArgumentException for
 *   unknown names, so catch it (or check the names yourself).
 *
 * - isAtLeast(level, threshold) is true when level is the same as threshold or
 *   later in the declaration order (ERROR is at least WARN, TRACE is not).
 *   Enum constants know their position through compareTo.
 *
 * - highest(tokens) returns the highest level among the tokens that parse,
 *   ignoring the ones that do not. When nothing parses it returns TRACE.
 *
 * Example: highest(new String[] {"info", "nope", "ERROR"}) -> ERROR
 */
enum LogLevel { TRACE, DEBUG, INFO, WARN, ERROR }

public class LogLevelParser {

    public static LogLevel parseOrDefault(String text, LogLevel fallback) {
        if (text == null) {
            return fallback;
        }
        try {
            return LogLevel.valueOf(text.trim().toUpperCase());
        } catch (IllegalArgumentException e) {
            return fallback;
        }
    }

    public static boolean isAtLeast(LogLevel level, LogLevel threshold) {
        return level.compareTo(threshold) >= 0;
    }

    public static LogLevel highest(String[] tokens) {
        LogLevel best = LogLevel.TRACE;
        for (String token : tokens) {
            LogLevel parsed = parseOrDefault(token, LogLevel.TRACE);
            if (isAtLeast(parsed, best)) {
                best = parsed;
            }
        }
        return best;
    }
}
